  <script>
    // Approach page planner
    function buildAPlan(){
      const goal = document.getElementById('aGoal').value;
      const intensity = parseInt(document.getElementById('aIntensity').value,10);
      const lines = [];
      lines.push('{{BUSINESS_NAME}} — Draft Plan');
      lines.push('Goal: '+goal);
      lines.push('Initial intensity: '+intensity+'/5');
      lines.push('\nWeek 1: Establish one measurable habit tied to goal and a simple tracker (daily check-in).');
      if(intensity>=4){
        lines.push('Weeks 2–6: Short check-ins every 1–2 weeks; introduce a second habit by week 3.');
      } else {
        lines.push('Weeks 2–8: Monthly check-ins with focused troubleshooting as needed.');
      }
      lines.push('\nSuggested measurements: symptom score, sleep log, 1 dietary/meal habit tracker.');
      lines.push('\nBring this to your first visit or paste into intake notes.');
      return lines.join('\n');
    }
    document.getElementById('aBuild').addEventListener('click',function(){document.getElementById('aOut').value = buildAPlan();});
    document.getElementById('aCopy').addEventListener('click',function(){navigator.clipboard.writeText(document.getElementById('aOut').value).then(()=>alert('Copied')).catch(()=>alert('Copy failed'))});

    // Inventory builder
    function buildInv(){
      const picked = Array.from(document.querySelectorAll('aside input[type=checkbox]')).filter(i=>i.checked).map(i=>i.value);
      if(!picked.length) return 'No areas selected.';
      const out = [];
      out.push('Initial intake agenda — selected: '+picked.join(', '));
      out.push('\n1) Top priority (pick one): '+picked[0]);
      out.push('2) Quick screen for other items: '+(picked.slice(1).length?picked.slice(1).join(', '):'None')); 
      out.push('\nRecommended cadence: '+(picked.length>3?'Biweekly for first 6 weeks':'Monthly with as-needed check-ins')); 
      out.push('\nBring: symptom logs, recent labs, med list.');
      return out.join('\n');
    }
    document.getElementById('invBuild').addEventListener('click',function(){document.getElementById('invOut').value = buildInv();});
    document.getElementById('invCopy').addEventListener('click',function(){navigator.clipboard.writeText(document.getElementById('invOut').value).then(()=>alert('Copied')).catch(()=>alert('Copy failed'))});
